// Validate x-api-key header for jobs endpoint
const headers = $input.item.json.headers;
const query = $input.item.json.query;
const apiKey = headers['x-api-key'];
const expectedKey = $env.ESTIMATOR_API_KEY;

if (!apiKey || apiKey !== expectedKey) {
  throw new Error('UNAUTHORIZED');
}

const customerId = query?.customerId;
if (!customerId) {
  throw new Error('customerId query parameter is required');
}

return { json: { authorized: true, customerId } };

// Transform JT jobs response and filter by Phase
const response = $input.item.json;
const customerId = $('Validate Auth (Jobs)').item.json.customerId;

// Phase custom field ID - phases 1-3 are estimating stages
const PHASE_FIELD_ID = '22P4fguBu3Ub';
const ESTIMATING_PHASES = ['1', '2', '3'];

if (response.errors && response.errors.length > 0) {
  throw new Error(`JT API error: ${response.errors[0].message}`);
}

const nodes = response.jobs?.nodes || [];

const jobs = nodes
  .map(node => {
    const phaseField = node.customFields?.nodes?.find(cf => cf.customFieldId === PHASE_FIELD_ID);
    const phase = phaseField?.value || null;

    return {
      id: node.id,
      number: node.number,
      name: node.name,
      status: node.status,
      phase: phase,
      displayName: `#${node.number} - ${node.name}`
    };
  })
  // Filter to only estimating phases (1-3) or jobs without phase set
  .filter(job => !job.phase || ESTIMATING_PHASES.includes(job.phase))
  // Sort by job number descending (newest first)
  .sort((a, b) => parseInt(b.number) - parseInt(a.number));

return { json: { jobs, count: jobs.length, customerId } };

const grantKey = $env.JOBTREAD_GRANT_KEY;

if (!grantKey) {
  throw new Error('Missing JOBTREAD_GRANT_KEY');
}

const query = {
  '$': { grantKey },
  organization: {
    '$': { id: '22Nm3uFevXMb' },
    id: {},
    accounts: {
      '$': {
        where: ['type', '=', 'customer'],
        size: 50,
        ...($input.first().json.page ? { page: $input.first().json.page } : {}),
      },
      nextPage: {},
      nodes: {
        id: {},
        name: {},
        primaryLocation: { id: {} },
        locations: {
          nodes: {
            id: {},
            name: {},
            address: {},
            city: {},
            postalCode: {},
          },
        },
      },
    },
  },
};

return [{ json: { query } }];

const response = $input.first().json;

if (response.errors?.length) {
  throw new Error(`JT API error: ${response.errors[0].message}`);
}

const nodes = response.organization?.accounts?.nodes ?? [];

const customers = nodes.map(node => {
  const locations = node.locations?.nodes ?? [];
  const primaryLocation =
    locations.find(l => l.id === node.primaryLocation?.id) ?? locations[0] ?? null;

  return {
    id: node.id,
    name: node.name,
    primaryLocationId: node.primaryLocation?.id,
    address: primaryLocation
      ? [primaryLocation.address, primaryLocation.city, primaryLocation.postalCode].filter(Boolean).join(', ')
      : null,
    locations: locations.map(l => ({
      id: l.id,
      name: l.name,
      address: [l.address, l.city, l.postalCode].filter(Boolean).join(', ') || null,
    })),
  };
}).sort((a, b) => a.name.localeCompare(b.name));

return [{ json: { version: 1, customers, count: customers.length, nextPage: response.organization?.accounts?.nextPage || null } }];

// Validate x-api-key header for customers endpoint
const headers = $input.item.json.headers;
const apiKey = headers['x-api-key'];
const expectedKey = $env.ESTIMATOR_API_KEY;

if (!apiKey || apiKey !== expectedKey) {
  throw new Error('UNAUTHORIZED');
}

const page = $input.item.json.query?.page;
if (page !== undefined && (typeof page !== 'string' || page.length > 2000)) throw new Error('INVALID_PAGE');
return { json: { authorized: true, page: page || null } };
